def copy_plot_perimeters_to_geojson(apps, schema_editor):
    Potrero = apps.get_model('core', 'Potrero')
    for plot in Potrero.objects.exclude(perimetro=[]).iterator():
        points = plot.perimetro
        if not isinstance(points, list) or len(points) < 3:
            continue
        if any(not isinstance(point, list) or len(point) != 2 for point in points):
            continue
        ring = [list(point) for point in points]
        if ring[0] != ring[-1]:
            ring.append(ring[0])
        plot.geojson = {
            'type': 'Feature',
            'properties': {},
            'geometry': {'type': 'Polygon', 'coordinates': [ring]},
        }
        plot.save(update_fields=['geojson'])


